shapes.current = brushes[brushes.i]

local mox,moy = 0,0
local trib = 18*3
function shapes.place(dt)
    mox,moy = love.mouse.getPosition()
    local shiftdn = press('rshift') or press('lshift')
    
    if not shiftdn then
        -- if shift was let go, save brush
            if shapes.brush then
                if #shapes.brush>0 then
                    local minx=shapes.brush[1][1]
                    local miny=shapes.brush[1][2]
                    local offx=0
                    for i,pc in ipairs(shapes.brush) do
                        if pc[1]<minx then minx=pc[1] end
                        if pc[2]<miny then miny=pc[2] end
                        --if pc.img==3 and (((pc[1]%2==1 and pc[2]%2==0) or (pc[1]%2==0 and pc[2]%2==1)) and not (pc[1]%2==pc[2]%2)) then offx=-1 end
                    end
                    if not ((miny%2==0 and minx%2==1) or (miny%2==1 and minx%2==0)) then offx=-1 end
                    for i,pc in ipairs(shapes.brush) do
                        pc[1]=pc[1]-minx+offx; pc[2]=pc[2]-miny
                    end

                    table.insert(brushes,shapes.brush)

                    brushes.i = #brushes
                    shapes.current = brushes[brushes.i]
                end

                for i,pc in ipairs(shapes) do pc.sel = nil end
                shapes.brush = nil
            end

        -- click to place a brush
            lastclick = click
            click = love.mouse.isDown(1)
            if click and not lastclick then
                for i,pc in ipairs(shapes.current) do
                    local gx,gy = shapes.gridcoord(mox,moy)
                    gx,gy = gx+pc[1],gy+pc[2]
                    table.insert(shapes,{img=pc.img,gx,gy})
                end
            end

        -- right-click to remove
            lastrclick = rclick
            rclick = love.mouse.isDown(2)
            if rclick then--and not lastrclick then
                for i=#shapes,1,-1 do
                    local sh = shapes[i]
                    for j,pc in ipairs(shapes.current) do
                        local gx,gy = shapes.gridcoord(mox,moy)
                        gx,gy = gx+pc[1],gy+pc[2]
                        if shapes.collide(sh,gx,gy) or 
                            (pc.img==1 and shapes.collide(sh,gx,gy+1)) or
                            (pc.img==2 and shapes.collide(sh,gx+1,gy)) or
                            (pc.img==3 and shapes.collide(sh,gx+1,gy)) then
                            table.remove(shapes,i)
                            break
                        end
                    end
                end
            end
        
        -- middle-click to cycle brush
            lastmclick = mclick
            mclick = love.mouse.isDown(3)
            if mclick and not lastmclick then
                brushes.i = brushes.i-1
                if brushes.i<1 then brushes.i=#brushes end
                shapes.current = brushes[brushes.i]
            end

    else -- shift is being pressed
        shapes.brush = shapes.brush or {}

        lastclick = click
        click = love.mouse.isDown(1)
        
        -- shift+a: auto-select all
            if tapped('a') then
                shapes.brush = {}
                for i,pc in ipairs(shapes) do
                    table.insert(shapes.brush,{img=pc.img,pc[1],pc[2]})
                    pc.sel = true
                end
            end

        if click and not lastclick then
            local gx,gy = math.floor(mox/(trib/2)),
                          math.floor(moy/(trib*sin(2*pi/3)))

            for i,pc in ipairs(shapes) do
                if shapes.collide(pc,gx,gy) then
                    table.insert(shapes.brush,{img=pc.img,pc[1],pc[2]})
                    pc.sel = true
                end
            end
        end
    end

    -- rotate brush
        if tapped('r') then
            -- first, calculate the center point of the brush.
                local cx,cy = 0,0
                for i,pc in ipairs(shapes.current) do
                    local offx,offy = 0,0
                    if pc.img==1 then offx,offy=0.5,1 end
                    if pc.img==2 then offx,offy=1,0.5 end
                    if pc.img==3 then offx,offy=1,0.5 end
                    cx = cx+pc[1]+offx; cy = cy+pc[2]+offy
                end
                cx = cx/#shapes.current; cy = cy/#shapes.current
            -- then, take each piece's angle and radius from the center point,
            -- and use them to calculate rotated points.
                for i,pc in ipairs(shapes.current) do
                    local px,py = (pc[1]-cx)*(trib/2),
                                  (pc[2]-cy)*(trib*sin(2*pi/3))
                    if pc.img==1 then px=px+trib/2; py=py+trib*sin(2*pi/3) end
                    if pc.img==2 then px=px+trib/4*3; py=py+trib*sin(2*pi/3)/2 end
                    if pc.img==3 then px=px+trib/4*3; py=py+trib*sin(2*pi/3)/2 end
                    
                    local r = math.sqrt(px^2+py^2)
                    local a = math.atan2(py,px)
                    local a2 = a + 2*pi/6
                    px = cx+cos(a2)*r; py = cy+sin(a2)*r
                    
                    pc.img = pc.img%3+1
                    
                    if pc.img==1 then px=px-trib/2; py=py-trib*sin(2*pi/3) end
                    if pc.img==2 then px=px-trib/4*3; py=py-trib*sin(2*pi/3)/2 end
                    if pc.img==3 then px=px-trib/4*3; py=py-trib*sin(2*pi/3)/2 end
                    
                    pc[1] = math.floor(px/(trib/2)+0.5); pc[2] = math.floor(py/(trib*sin(2*pi/3))+0.5)
                end
            -- detect & fix misaligned
                local offx=0
                for i,pc in ipairs(shapes.current) do
                    if pc.img==1 and not (pc[2]%2==pc[1]%2) then offx=-1; break end
                    if pc.img==2 and not (pc[2]%2==pc[1]%2) then offx=-1; break end
                    if pc.img==3 and (pc[2]%2==pc[1]%2) then offx=-1; break end
                end
                for i,pc in ipairs(shapes.current) do
                    pc[1]=pc[1]+offx
                end
        end
end

function shapes.wait(dt)
    if tapped('g') then
        if system.find('draw',shapes.griddraw) then
             system.cease('draw', shapes.griddraw)
        else system.follow('draw',shapes.griddraw,1) 
        end
    end
    if tapped('h') then
        if system.find('update',shapes.histanim) then
            system.cease('update', shapes.histanim)
            shapes.history = nil
        else 
            system.follow('update',shapes.histanim) 
            shapes.history = 0
        end
    end
    if tapped('c') then
        if not system.find('update',shapes.clear) then
            system.follow('update',shapes.clear)
        end
    end
    if tapped('delete') then
        if brushes.i>3 then
            table.remove(brushes,brushes.i)
            if brushes.i>#brushes then 
                brushes.i = #brushes 
            end
            shapes.current = brushes[brushes.i]
        end
    end
    for i=1,9 do
        if tapped(tostring(i)) then
            if i<=#brushes then 
                brushes.i = i
                shapes.current = brushes[brushes.i]
            end
        end
    end
    if tapped('b') then
        local save = '{'
        for i,pc in ipairs(shapes.current) do
            save=save..string.format('{img=%d,%d,%d},',pc.img,pc[1],pc[2])
        end
        save = string.sub(save,1,#save-1) -- remove trailing comma
        save = save..'}'
        print(save)
    end
    if tapped('p') then
        palette.i = palette.i+1
        if palette.i > #palette then 
            palette.i = 0
            asset.pieces[1] = asset.piece1
            asset.pieces[2] = asset.piece2
        elseif palette.i == 1 then
            asset.pieces[1] = asset.piece1b
            asset.pieces[2] = asset.piece2b
        end
    end
    if tapped('i') then
        shapes.anim = not shapes.anim
        shapes.at = shapes.at or 0
    end
    if tapped('m') then
        if system.find('update',shapes.moveanim) then
            system.cease('update', shapes.moveanim)
            shapes.move = false
        else 
            system.follow('update',shapes.moveanim) 
            shapes.move = true
        end
    end
end

function shapes.clear(dt)
    if #shapes==0 then system.cease('update',shapes.clear) end
    table.remove(shapes,#shapes)
end

function shapes.histanim(dt)
    shapes.history = shapes.history+1
    if shapes.history>#shapes then 
        system.cease('update',shapes.histanim)
        shapes.history = nil
    end
end

function shapes.moveanim(dt)
    if t%3>0 then return end

    shapes.turn = shapes.turn or #shapes

    local board = {}
    for i,sh in ipairs(shapes) do
        table.insert(board,{img=sh.img,sh[1],sh[2]})
    end

    local sh = shapes[shapes.turn]
    if not sh.dx then
        local dx,dy
        if sh.img==1 then dx,dy = 0,-2 end
        if sh.img==2 then dx,dy = 1,-1 end
        if sh.img==3 then dx,dy =-1,-1 end
        sh.dx,sh.dy = dx,dy
    end

    sh[1] = sh[1]+sh.dx; sh[2] = sh[2]+sh.dy

    for i2,sh2 in ipairs(board) do
        if not (sh2[1]==sh[1]-sh.dx and sh2[2]==sh[2]-sh.dy) and (shapes.collide(sh2,sh[1],sh[2]) or 
            (sh.img==1 and shapes.collide(sh2,sh[1],sh[2]+1)) or
            (sh.img==2 and shapes.collide(sh2,sh[1]+1,sh[2])) or
            (sh.img==3 and shapes.collide(sh2,sh[1]+1,sh[2]))) then
            sh.dx,sh.dy = -sh.dx,-sh.dy
            sh[1] = sh[1]+sh.dx; sh[2] = sh[2]+sh.dy
            break
        end
    end
    shapes.turn = shapes.turn-1
    if shapes.turn<1 then shapes.turn=#shapes end
end

function shapes.gridcoord(mox,moy)
    mox = mox-26; moy = moy-26
    local gx,gy = math.floor(mox/(trib/2)),
                  math.floor(moy/(trib*sin(2*pi/3)))
    gx = gx+gx%2
    if gx%2==0 and gy%2==0 then gx=gx+1 end
    if gy%2==1 and gx%2==1 then gy=gy+1 end
    if brushes.i==3 then gx=gx-1 end
    return gx,gy
end

function shapes.collide(sh,gx,gy)
    if sh[1]==gx and sh[2]==gy then return true end
    if sh.img==1 and sh[1]==gx and sh[2]+1==gy then return true end
    if sh.img==2 and sh[1]+1==gx and sh[2]==gy then return true end
    if sh.img==3 and sh[1]+1==gx and sh[2]==gy then return true end
end

function shapes.scrncoord(gx,gy)
    return gx*(trib/2),gy*(trib*sin(2*pi/3))
end

