    fg(palette.grid())
    --[[local trib = 18*2
    local trigap = 7.8
    for tx=0,SW,trib*2-trib/trigap do
    lg.line(tx-trib/trigap+trib+cos(0-pi/2)*trib,trib+sin(0-pi/2)*trib,tx-trib/trigap+trib+cos(2*pi/3-pi/2)*trib,trib+sin(2*pi/3-pi/2)*trib)
    lg.line(tx-trib/trigap+trib+cos(2*pi/3-pi/2)*trib,trib+sin(2*pi/3-pi/2)*trib,tx-trib/trigap+trib+cos(2*pi/3*2-pi/2)*trib,trib+sin(2*pi/3*2-pi/2)*trib)
    lg.line(tx-trib/trigap+trib+cos(2*pi/3*2-pi/2)*trib,trib+sin(2*pi/3*2-pi/2)*trib,tx-trib/trigap+trib+cos(0-pi/2)*trib,trib+sin(0-pi/2)*trib)
    lg.line(tx+trib*2-trib/trigap+cos(0+pi/2)*trib,trib-trib/2+sin(0+pi/2)*trib,tx+trib*2-trib/trigap+cos(2*pi/3+pi/2)*trib,trib-trib/2+sin(2*pi/3+pi/2)*trib)
    lg.line(tx+trib*2-trib/trigap+cos(2*pi/3+pi/2)*trib,trib-trib/2+sin(2*pi/3+pi/2)*trib,tx+trib*2-trib/trigap+cos(2*pi/3*2+pi/2)*trib,trib-trib/2+sin(2*pi/3*2+pi/2)*trib)
    lg.line(tx+trib*2-trib/trigap+cos(2*pi/3*2+pi/2)*trib,trib-trib/2+sin(2*pi/3*2+pi/2)*trib,tx+trib*2-trib/trigap+cos(0+pi/2)*trib,trib-trib/2+sin(0+pi/2)*trib)
    end]]
    -- contributed by Stefan
    for i=0,SH,trib*sin(2*pi/3) do--trib*0.866 do
        lg.line(0,i,SW,i)
    end
    for i=0,SW+trib*12,trib do
        local ax,ay = i,0
        lg.line(ax,ay,ax+cos(2*pi/3)*SW,ay+sin(2*pi/3)*SW)
    end
    for i=-trib*12,SW,trib do
        local ax,ay = i,0
        lg.line(ax,ay,ax+cos(pi-2*pi/3)*SW,ay+sin(pi-2*pi/3)*SW)
    end
end

function shapes.piecedraw()
    for i,pc in ipairs(shapes) do
        if shapes.history and i>shapes.history then break end
        if shapes.anim and (i*0.08+shapes.at*0.024)%4<1.2 then goto continue end
        
        fg(palette[palette.i]({piece=pc,i=i,t=t}))
        
        if pc.sel then fg(palette.sel()) end
        if shapes.brush then
            local gx2,gy2 = math.floor(mox/(trib/2)),
                            math.floor(moy/(trib*sin(2*pi/3)))
            if shapes.collide(pc,gx2,gy2) then
                fg(1,1,1,1)
                if (palette.i==9  and pc.img==1) or
                   (palette.i==10 and pc.img==2) or
                   (palette.i==11 and pc.img==3) then
                    fg(0.8,0.8,1,1)
                end
            end
        end
        --::continue::
        -- alpha fade
            --if shapes.anim and (i*0.08+t*0.024)%4<1.2 then 
            --    local r,g,b,a = lg.getColor()
            --    fg(r,g,b,1-(i*0.08+t*0.024)%4*1/1.2)
            --end
        lg.draw(asset.pieces[pc.img],pc[1]*(trib/2),pc[2]*(trib*sin(2*pi/3)))
        ::continue::
    end

    if shapes.anim and not press('t') then shapes.at = shapes.at+1 end

    if shapes.brush then return end

    for i,pc in ipairs(shapes.current) do
        local gx,gy = shapes.gridcoord(mox,moy)
        gx,gy = gx+pc[1],gy+pc[2]

        -- show snapped projection
            --fg(0.3,0.9,1,1)
            fg(1,1,1,1)
            if (palette.i==9  and pc.img==1) or
               (palette.i==10 and pc.img==2) or
               (palette.i==11 and pc.img==3) then
                fg(0.8,0.8,1,1)
            end
            if t%56<42 then lg.draw(asset.pieces[pc.img],shapes.scrncoord(gx,gy)) end

        -- flicker current shape at mouse pos
            --fg(1,1,1,0.5+sin(t*0.12)*0.5)
            --lg.draw(asset.pieces[pc.img],mox+pc[1]*trib/2,moy+pc[2]*trib*sin(2*pi/3))
    
        -- debug coordinates
            fg(0.7,0.4,0.4,1)
            lg.print(string.format('%d,%d',mox,moy),gx*trib/2,gy*trib*sin(2*pi/3)+asset.pieces[pc.img]:getHeight()-lg.getFont():getHeight('0'))
            lg.print(string.format('%d,%d',gx,gy),gx*trib/2,gy*trib*sin(2*pi/3)+asset.pieces[pc.img]:getHeight())        
    end
end